SELECT count(*) FROM public.lineitem lineitem WHERE EXISTS (SELECT 1 FROM public.orders o, public.customer c, public.supplier s, public.partsupp ps, public.part p, public.nation n WHERE o.o_orderkey = lineitem.l_orderkey AND c.c_custkey = o.o_custkey AND s.s_suppkey = lineitem.l_suppkey AND ps.ps_partkey = lineitem.l_partkey AND ps.ps_suppkey = lineitem.l_suppkey AND p.p_partkey = lineitem.l_partkey AND s.s_nationkey = c.c_nationkey AND n.n_nationkey = c.c_nationkey AND n.n_regionkey = 1 AND p.p_brand = 'Brand#12' AND ps.ps_availqty >= 5000) AND EXISTS (SELECT 1 FROM public.orders o WHERE o.o_orderkey = lineitem.l_orderkey AND o.o_orderpriority = '1-URGENT');
